    "/sync": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        /**
         * What changed for this reader since a moment
         * @description For a client that has been reading offline. Returns this person's own
         *     marks and reading positions that changed after `since`, the marks that
         *     were DELETED, and the server's own clock as `until`.
         *
         *     When `more` comes back true, a page was filled and another is
         *     waiting: send the `cursor` this response carries back as the `cursor`
         *     parameter to get the NEXT page. Do not re-send `since` to page - it is
         *     not what advances a page and never was; resending it just re-reads the
         *     same starting window; `since` only matters for the FIRST call of a
         *     round. `cursor` is opaque - store and return exactly what was given,
         *     never construct one.
         *
         *     Only once `more` comes back false - the round is finished - store
         *     `until` as the next `since` and discard the cursor. `until` is the
         *     server's clock at that final read, never the client's own: two clocks
         *     a minute apart would silently lose or repeat a minute of somebody's
         *     reading. A fresh round (no `cursor`) actually reads from a couple of
         *     seconds before `since`, because a row's timestamp is set when its
         *     statement runs and becomes visible only when its transaction commits,
         *     which is later - a row can be freshly written but not yet visible to
         *     the exact moment `since` names. That overlap applies once, at the
         *     start of a round; it does not reopen between pages of the same round,
         *     so it cannot trap paging behind a burst of changes that share one
         *     instant - repeats are free regardless, because every apply is keyed
         *     by id.
         *
         *     A client that never adopts `cursor` still works for whatever fits in
         *     one page: send `since`, read the results, ignore `more`. It will not
         *     make progress past the first page of a round that does not fit,
         *     which is exactly the paging `cursor` exists for.
         *
         *     Deletions are listed rather than implied. An absent mark is
         *     indistinguishable from one the client has not been told about yet, so
         *     without this a highlight deleted on a laptop comes back the next time
         *     the phone syncs.
         *
         *     Scoped to this person's OWN marks. Somebody else's shared highlights
         *     are readable in the reader and are not theirs to carry away and edit.
         */
        get: {
            parameters: {
                query?: {
                    /**
                     * @description RFC3339. Absent means everything, which is what a fresh install
                     *     wants. Ignored when `cursor` is present - `cursor` already knows
                     *     where a round in progress left off.
                     */
                    since?: string;
                    /**
                     * @description Resumes a round in progress. Only ever a value this endpoint
                     *     returned as `cursor` on an earlier page of the SAME round; sending
                     *     back an old or unrelated one is a 400, not a silent reset to page
                     *     one.
                     */
                    cursor?: string;
                    limit?: number;
                };
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody?: never;
            responses: {
                /** @description Everything that changed */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["SyncPull"];
                    };
                };
                400: components["responses"]["BadRequest"];
                401: components["responses"]["Unauthorized"];
            };
        };
        put?: never;
        /**
         * What this client did while it was away
         * @description Marks made, edited or deleted offline, and where books were left.
         *
         *     Every mark carries an id the CLIENT generated and a timestamp of when
         *     the CLIENT made the change. Both matter. The id makes this safe to
         *     repeat - the connection that drops is the one carrying the response -
         *     and the timestamp is what decides conflicts, because a phone that was
         *     in a tunnel for a week did not edit anything at the moment it found
         *     signal.
         *
         *     Marks resolve last-write-wins by that timestamp, per mark. A deletion
         *     beats an edit: a mark that comes back from the dead is the failure
         *     people notice, and an edit lost to a delete looks like the delete they
         *     asked for. A mark the server holds a newer version of comes back
         *     `stale`, and the newer version arrives on the next pull.
         *
         *     Positions are not last-write-wins, because a position is two facts.
         *     Where the reader IS takes the newest by the reader's clock, backwards
         *     included - turning back a chapter is reading. How far they GOT only
         *     ever advances, from any device, with no clock involved, so a laptop
         *     that opened chapter one cannot erase an evening's reading on a phone.
         *
         *     One refused book does not discard the rest of the push.
         */
        post: {
            parameters: {
                query?: never;
                header?: never;
                path?: never;
                cookie?: never;
            };
            requestBody: {
                content: {
                    "application/json": components["schemas"]["SyncPush"];
                };
            };
            responses: {
                /** @description What became of each pushed mark */
                200: {
                    headers: {
                        [name: string]: unknown;
                    };
                    content: {
                        "application/json": components["schemas"]["SyncPushResult"];
                    };
                };
                400: components["responses"]["BadRequest"];
                401: components["responses"]["Unauthorized"];
            };
        };
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
